<node CREATED="1269444352384" ID="Freemind_Link_370717406" MODIFIED="1269812437571" POSITION="right" TEXT="&#xbf;Qu&#xe9; es ser emprendedor?">
<icon BUILTIN="full-1"/>
<node CREATED="1269444385713" ID="Freemind_Link_899994793" MODIFIED="1269444529306" TEXT="Emprendedor es una persona que detecta una oportunidad y crea una organizaci&#xf3;n (o la adquiere o es parte de un grupo que lo hace) para ponerse al frente de ella"/>
<node CREATED="1269444648914" ID="Freemind_Link_1089575939" MODIFIED="1269446306470" TEXT="El proceso emprendedor comprende todas las actividades relacionadas con detectar oportunidades y crear organizaciones para concretarlas"/>
<node CREATED="1269447347906" ID="Freemind_Link_1634551258" MODIFIED="1269450684924" TEXT="11 condiciones determinantes detr&#xe1;s del emprendedor">
<node CREATED="1269447381028" ID="Freemind_Link_1627305043" MODIFIED="1269447405513" TEXT="Emancipaci&#xf3;n"/>
<node CREATED="1269447406677" ID="Freemind_Link_1793379297" MODIFIED="1269447589936" TEXT="Moderaci&#xf3;n en la ambici&#xf3;n de dinero"/>
<node CREATED="1269447423921" ID="Freemind_Link_1926855952" MODIFIED="1269447464088" TEXT="Pasi&#xf3;n"/>
<node CREATED="1269447465008" ID="Freemind_Link_1586526364" MODIFIED="1269447477546" TEXT="Resultados"/>
<node CREATED="1269447478474" ID="Freemind_Link_91968495" MODIFIED="1269447521018" TEXT="Espiritualidad"/>
<node CREATED="1269447521599" ID="Freemind_Link_672371149" MODIFIED="1269447557142" TEXT="Novicio (actitud de aprendiz)"/>
<node CREATED="1269447557792" ID="Freemind_Link_389425104" MODIFIED="1269447610167" TEXT="Disfrute del camino"/>
<node CREATED="1269447610802" ID="Freemind_Link_359626032" MODIFIED="1269447652938" TEXT="&#xc9;xitos compartidos"/>
<node CREATED="1269447653495" ID="Freemind_Link_497284382" MODIFIED="1269447710520" TEXT="Determinaci&#xf3;n"/>
<node CREATED="1269447711404" ID="Freemind_Link_329690839" MODIFIED="1269447724202" TEXT="Optimismo y sue&#xf1;os"/>
<node CREATED="1269447724791" ID="Freemind_Link_113928191" MODIFIED="1269447803723" TEXT="Responsabilidad incondicional (protagonismo)"/>
</node>
<node CREATED="1269447898635" ID="Freemind_Link_125244946" MODIFIED="1269448040270" TEXT="El emprendedor brillante siempre logra finalmente el capital o el gran proyecto. El emprendedor mediocre, por m&#xe1;s que tenga un padre rico y generoso, no es exitoso"/>
<node CREATED="1269448811125" ID="Freemind_Link_332156847" MODIFIED="1269448993536" TEXT="Emprendedor, se nace o se hace">
<node CREATED="1269448995160" ID="Freemind_Link_565599108" MODIFIED="1269449009046" TEXT="Niveles de an&#xe1;lisis">
<node CREATED="1269449010315" ID="Freemind_Link_1646358643" MODIFIED="1269449044823" TEXT="Talentos - Inmodificable">
<node CREATED="1269450156678" ID="Freemind_Link_1884778909" MODIFIED="1269450194718" TEXT="Capa neuronal de talentos inmodificables, que se tienen o no"/>
<node CREATED="1269450275892" ID="Freemind_Link_880606285" MODIFIED="1269450527232" TEXT="Patrones recurrentes de pensamiento y comportamiento que pertenecen a la fisiolog&#xed;a de cada uno, producto de la gen&#xe9;tica y las influencias anteriores a la pubertad que determinan el sistema neurol&#xf3;gico"/>
</node>
<node CREATED="1269449045765" ID="Freemind_Link_724269803" MODIFIED="1269450684925" TEXT="Metahabilidades - Tal vez modificable">
<arrowlink DESTINATION="Freemind_Link_1634551258" ENDARROW="Default" ENDINCLINATION="345;0;" ID="Freemind_Arrow_Link_1386526568" STARTARROW="None" STARTINCLINATION="345;0;"/>
<node CREATED="1269450733619" ID="Freemind_Link_959993650" MODIFIED="1269450748689" TEXT="Desarrollar las 11 condiciones"/>
<node CREATED="1269450750930" ID="Freemind_Link_1684517538" MODIFIED="1269450860196" TEXT="Permitirse so&#xf1;ar, asumir un papel de protagonista continuamente dispuesto al aprendizaje y el trabajo interno"/>
<node CREATED="1269450861130" ID="Freemind_Link_819690066" MODIFIED="1269450977745" TEXT="Desarrollar su autoestima para lograr mayor firmeza en sus decisiones"/>
<node CREATED="1269450978633" ID="Freemind_Link_7120552" MODIFIED="1269451028805" TEXT="Enamorarse con pasi&#xf3;n de su proyecto y comprometerse incondicionalmente con &#xe9;l"/>
<node CREATED="1269451038470" ID="Freemind_Link_1197325253" MODIFIED="1269451058975" TEXT="Aprender a compartir con su equipo"/>
<node CREATED="1269451059625" ID="Freemind_Link_1842316166" MODIFIED="1269451079597" TEXT="Tomar riesgos para lograr su independencia"/>
<node CREATED="1269451087952" ID="Freemind_Link_569816888" MODIFIED="1269451121432" TEXT="Aprender a divertirse en el proceso de sus propios aciertos y errores"/>
</node>
<node CREATED="1269449081920" ID="Freemind_Link_1313685700" MODIFIED="1269449121546" TEXT="H&#xe1;bitos t&#xe9;cnicos - Claramente modificables">
<node CREATED="1269449328763" ID="Freemind_Link_1383457662" MODIFIED="1269449357733" TEXT="Tienen que ver con la formaci&#xf3;n y el aprendizaje educativo"/>
<node CREATED="1269449757699" ID="Freemind_Link_736344360" MODIFIED="1269449831908" TEXT="Son conocimientos y habilidades que se adquieren con capacitaci&#xf3;n acad&#xe9;mica y aprendizaje t&#xe9;cnico"/>
<node CREATED="1269449928515" ID="Freemind_Link_1228806976" MODIFIED="1269450008020" TEXT="Resume todo el trabajo que se puede hacer, aprendiendo en la dimensi&#xf3;n t&#xe9;cnica las claves del proceso emprendedor"/>
<node CREATED="1269450013082" ID="Freemind_Link_1998621658" MODIFIED="1269450120499" TEXT="Formaci&#xf3;n universitaria, interacciones con mentores, estudios de una rama de actividad para aprender c&#xf3;mo funciona"/>
<node CREATED="1269449365629" ID="Freemind_Link_1292108374" MODIFIED="1269450591606" TEXT="Para poder responder:">
<node CREATED="1269449384408" ID="Freemind_Link_1797720999" MODIFIED="1269449423573" TEXT="&#xbf;Qu&#xe9; es un resumen de condiciones?"/>
<node CREATED="1269449426865" ID="Freemind_Link_1188722914" MODIFIED="1269449607530" TEXT="&#xbf;C&#xf3;mo lograr una apertura de capital?"/>
<node CREATED="1269449611264" ID="Freemind_Link_816508732" MODIFIED="1269449678793" TEXT="&#xbf;C&#xf3;mo desarrollar una estrategia comercial y finaciera?"/>
<node CREATED="1269449683367" ID="Freemind_Link_1210680975" MODIFIED="1269449722431" TEXT="&#xbf;C&#xf3;mo armar un plan de negocios?"/>
</node>
</node>
</node>
</node>
<node CREATED="1269451261850" FOLDED="true" ID="Freemind_Link_1893973794" MODIFIED="1269820099364" TEXT="&#xbf;Por qu&#xe9; emprender?">
<node CREATED="1269451292441" ID="Freemind_Link_432415298" MODIFIED="1269451390083" TEXT="3 tipos de motivaciones:">
<node CREATED="1269451392895" ID="Freemind_Link_1051054136" MODIFIED="1269451403753" TEXT="Los luchadores">
<node CREATED="1269451452484" ID="Freemind_Link_1479294999" MODIFIED="1269451627687" TEXT="Son quienes ven el proceso emprendedor como la &#xfa;nica manera de subsistir, ante la imposibilidad de ser parte de un proyecto existente"/>
<node CREATED="1269451678249" ID="Freemind_Link_1421382889" MODIFIED="1269451696668" TEXT="Aqu&#xe9;l que en verdad no decide ser emprendedor"/>
<node CREATED="1269451732566" ID="Freemind_Link_654836485" MODIFIED="1269451753884" TEXT="Emprende porque es la &#xfa;nica alternativa que tiene"/>
</node>
<node CREATED="1269451404662" ID="Freemind_Link_1227019133" MODIFIED="1269451417902" TEXT="Los caza-olas">
<node CREATED="1269451799013" ID="Freemind_Link_106653670" MODIFIED="1269451893954" TEXT="Son quienes se montan en grandes ondas de moda en busca de fortuna"/>
<node CREATED="1269451917183" ID="Freemind_Link_1430902317" MODIFIED="1269451933415" TEXT="Dependen del boom del momento"/>
</node>
<node CREATED="1269451418855" ID="Freemind_Link_1770040411" MODIFIED="1269451429372" TEXT="Los gladiadores">
<node CREATED="1269451970454" ID="Freemind_Link_711633392" MODIFIED="1269452036514" TEXT="Son quienes sienten el proceso emprendedor en la sangre y van a hacerlo independientemente del contexto"/>
<node CREATED="1269452037459" ID="Freemind_Link_1506753449" MODIFIED="1269452089426" TEXT="Eligen esta actividad como su profesi&#xf3;n"/>
<node CREATED="1269452090252" ID="Freemind_Link_777185499" MODIFIED="1269452141354" TEXT="Se comprometen con lo que realizan, m&#xe1;s all&#xe1; de las modas o las circunstancias"/>
<node CREATED="1269452148521" ID="Freemind_Link_559230454" MODIFIED="1269452162471" TEXT="Son los emprendedores, sin m&#xe1;s"/>
</node>
</node>
</node>
<node CREATED="1269812171032" FOLDED="true" ID="Freemind_Link_1050505144" MODIFIED="1269812195736" TEXT="La diferencia entre &#xe9;xito y fracaso">
<node CREATED="1269812198469" ID="Freemind_Link_1962232269" MODIFIED="1269812371502" TEXT="El proceso emprendedor tiene una cantidad enorme de obst&#xe1;culos, y la diferencia entre los emprendedores exitosos y quienes no lo son est&#xe1;, justamente, en la manera de afrontar la entereza y altura esas dificultades"/>
</node>
</node>
<node CREATED="1269812414025" ID="Freemind_Link_484828762" MODIFIED="1269812440528" POSITION="right" TEXT="Reconocer la oportunidad">
<icon BUILTIN="full-2"/>
<node CREATED="1269812545652" ID="Freemind_Link_1344005478" MODIFIED="1269812559524" TEXT="Una idea simple"/>
<node CREATED="1269812560512" ID="Freemind_Link_1753855265" MODIFIED="1269820036683" TEXT="&#xbf;De d&#xf3;nde surgen las ideas?"/>
<node CREATED="1269812588333" FOLDED="true" ID="Freemind_Link_1531114277" MODIFIED="1269812615263" TEXT="Buenas viejas ideas">
<node CREATED="1269812647324" ID="Freemind_Link_685443041" MODIFIED="1269812757174" TEXT="La clave no est&#xe1; en la originalidad de la idea. El &#xe9;xito proviene de haberla puesta en pr&#xe1;ctica mejor que los dem&#xe1;s"/>
</node>
<node CREATED="1269812615910" FOLDED="true" ID="Freemind_Link_251697311" MODIFIED="1269812917938" TEXT="Una gu&#xed;a para detectar oportunidades: el proceso Lupa Deductiva">
<font NAME="SansSerif" SIZE="12"/>
<node CREATED="1269812895824" ID="Freemind_Link_390010388" MODIFIED="1269816329899" TEXT="Lupa General: definir las &#xe1;reas de actividad">
<icon BUILTIN="full-1"/>
<node CREATED="1269813178623" FOLDED="true" ID="Freemind_Link_1504008384" MODIFIED="1269813376370" TEXT="El emprendedor potencial debe hacer una lista de todas las &#xe1;reas relacionadas con la actividad que hoy est&#xe1; realizando">
<node CREATED="1269813449261" FOLDED="true" ID="Freemind_Link_1134298573" MODIFIED="1269813475215" TEXT="Por ejemplo hacerse las siguientes preguntas:">
<node CREATED="1269813496364" FOLDED="true" ID="Freemind_Link_97534850" MODIFIED="1269813595844" TEXT="&#xbf;Qu&#xe9; actividades involucra la fabricaci&#xf3;n y comercializaci&#xf3;n de jabones?">
<node CREATED="1269813636767" ID="Freemind_Link_19699894" MODIFIED="1269813977427" TEXT="Manufactura de productos de consumo masivo (incluyendo  eventualmente  la importaci&#xf3;n de productos de compra masiva)">
<icon BUILTIN="full-1"/>
</node>
<node CREATED="1269813732227" ID="Freemind_Link_1649765672" MODIFIED="1269813987081" TEXT="Comercializaci&#xf3;n de productos en supermercados (venta de productos a cadenas, etc.)">
<icon BUILTIN="full-2"/>
</node>
<node CREATED="1269813798633" ID="Freemind_Link_35409287" MODIFIED="1269813990888" TEXT="Industria de la publicidad (incluidas las empresas de medios como revistas, canales de televisi&#xf3;n, emisoras de radio)">
<icon BUILTIN="full-3"/>
</node>
<node CREATED="1269813876147" ID="Freemind_Link_213410006" MODIFIED="1269813994350" TEXT="Empresas de dise&#xf1;o de productos (dise&#xf1;adores gr&#xe1;ficos e industriales)">
<icon BUILTIN="full-4"/>
</node>
</node>
</node>
</node>
</node>
<node CREATED="1269813008740" ID="Freemind_Link_1827976131" MODIFIED="1269816331318" TEXT="Lupa Mundial: elegir una actividad y aprender de ella enfoc&#xe1;ndose en mercados desarrollados">
<icon BUILTIN="full-2"/>
<node CREATED="1269814078810" FOLDED="true" ID="Freemind_Link_251915242" MODIFIED="1269814212818" TEXT="Poner un puntaje de preferencias a las actividades de la lista, elegir la que uno m&#xe1;s le gusta y dedicarse a aprender y a leer todo lo que haya disponible sobre esa industria en mercados desarrollados">
<node CREATED="1269814267074" FOLDED="true" ID="Freemind_Link_627986868" MODIFIED="1269814354083" TEXT="Aprender sobre los mercados, es muy sencillo, a trav&#xe9;s de una gran variedad de portales de Internet">
<node CREATED="1269814775765" FOLDED="true" ID="Freemind_Link_13613270" MODIFIED="1269814802895" TEXT="Estudios de sectores (Industry surveys)">
<node CREATED="1269814585711" ID="Freemind_Link_55263194" MODIFIED="1269814653160" TEXT="Standards &amp; Poors (www.standardandpoors.com)"/>
<node CREATED="1269814653835" ID="Freemind_Link_1625757424" MODIFIED="1269814675849" TEXT="Hoovers (www.hovers.com)"/>
</node>
<node CREATED="1269814813260" FOLDED="true" ID="Freemind_Link_1300180947" MODIFIED="1269814844774" TEXT="Datos de las empresas que cotizan en la bolsa">
<node CREATED="1269814846215" ID="Freemind_Link_1144637970" MODIFIED="1269814865514" TEXT="www.sec.gov"/>
<node CREATED="1269814866440" ID="Freemind_Link_102784755" MODIFIED="1269814880981" TEXT="finance.yahoo.com"/>
</node>
<node CREATED="1269814905183" ID="Freemind_Link_365712932" MODIFIED="1269814980299" TEXT="Otra forma de obtener informaci&#xf3;n es comprando publicaciones del Small Business Sourcebook"/>
</node>
<node CREATED="1269814359888" FOLDED="true" ID="Freemind_Link_919197120" MODIFIED="1269814403352" TEXT="Ver qu&#xe9; compa&#xf1;&#xed;as cotizan en la bolsa de Estados Unidos">
<node CREATED="1269814406754" ID="Freemind_Link_1084305126" MODIFIED="1269814465487" TEXT="Cu&#xe1;les operan en las distintas industrias y acceder a datos b&#xe1;sicos sobre sus actividades"/>
</node>
<node CREATED="1269814481465" ID="Freemind_Link_1819309919" MODIFIED="1269814558338" TEXT="Adquirir reportes por sector comparan las empresas de ese ramo y las perspectivas del mercado"/>
</node>
</node>
<node CREATED="1269813147754" ID="Freemind_Link_185294599" MODIFIED="1269816333487" TEXT="Lupa Local: conocer el propio mercado de ese sector">
<icon BUILTIN="full-3"/>
<node CREATED="1269815700288" ID="Freemind_Link_1592534263" MODIFIED="1269815733113" TEXT="Hacer el mismo ejercicio anterior, pero para el mercado local"/>
<node CREATED="1269815748297" ID="Freemind_Link_990490328" MODIFIED="1269815775724" TEXT="Aqu&#xed; es donde se ve el beneficio de estar en un pa&#xed;s emergente">
<node CREATED="1269815784419" ID="Freemind_Link_1086093720" MODIFIED="1269815825839" TEXT="Uno puede analizar las disparidades respecto del mercado desarrollado"/>
<node CREATED="1269815831898" ID="Freemind_Link_841401173" MODIFIED="1269815858139" TEXT="De all&#xed;, hacer inferencias sobre qu&#xe9; va a pasar"/>
<node CREATED="1269815864541" ID="Freemind_Link_1790819742" MODIFIED="1269815925539" TEXT="A qu&#xe9; velocidad para que el mercado local converja hacia lo que ocurre en los pa&#xed;ses desarrollados"/>
<node CREATED="1269815954935" ID="Freemind_Link_678179285" MODIFIED="1269816021019" TEXT="As&#xed; podemos detectar si en el mercado local todav&#xed;a existe una gran fragmentaci&#xf3;n del sector"/>
</node>
<node CREATED="1269816065952" ID="Freemind_Link_1252300801" MODIFIED="1269816242578" TEXT="Es fundamental saber qui&#xe9;nes son los jugadores de importancia, charlar con ellos, visitarlos, pedirles que nos ense&#xf1;en sobre el sector y si no son muy voluntariosos encontrar la forma de actuar como comprador misterioso para entender qu&#xe9; ventajas ofrecen al cliente"/>
<node CREATED="1269816258605" ID="Freemind_Link_100536338" MODIFIED="1269816316420" TEXT="Concurrir a las conferencias y convenciones locales del sector, donde se suelen concentrar todos los jugadores importantes"/>
</node>
<node CREATED="1269816720435" FOLDED="true" ID="Freemind_Link_1414995701" MODIFIED="1269817126973" TEXT="Lupa Din&#xe1;mica: analizar el curso probable">
<icon BUILTIN="full-4"/>
<node CREATED="1269816762781" FOLDED="true" ID="Freemind_Link_692977331" MODIFIED="1269816862717" TEXT="Hacer un profundo an&#xe1;lisis sobre los factores de peso que determinan que las diferencias entre los mercados desarrollados y no desarrollados puedan perdurar o tiendan a converger">
<node CREATED="1269816872800" ID="Freemind_Link_439788839" MODIFIED="1269817113588" TEXT="Es decir, precisar mediante un an&#xe1;lisis muy minucioso cu&#xe1;l es la din&#xe1;mica m&#xe1;s probable en la rama o el sector donde vamos a iniciar un emprendimiento">
<hook NAME="accessories/plugins/NodeNote.properties">
<text>Para comprender mejor el autor se&#xf1;ala en su libro dos ejemplos, uno sobre McDonald&apos;s y el otro sobre las tintorer&#xed;as en el cono sur&#xa;</text>
</hook>
</node>
</node>
</node>
<node CREATED="1269817129693" ID="Freemind_Link_418333390" MODIFIED="1269817163157" TEXT="Lupa Fina: enfocarse en lo particular">
<icon BUILTIN="full-5"/>
<node CREATED="1269817192553" ID="Freemind_Link_1754435884" MODIFIED="1269817332846" TEXT="Si el emprendedor recorri&#xf3; los cuatro pasos detallados, lleg&#xf3; a un punto en el que sabe que hay una actividad con la que tiene una relativa afinidad y en la que existe una brecha convergente entre los pa&#xed;ses desarrollados y no desarrollados"/>
<node CREATED="1269817355971" FOLDED="true" ID="Freemind_Link_1163003015" MODIFIED="1269817411025" TEXT="Requiere un esfuerzo para enfocarse al m&#xe1;ximo. Hay que ir de lo global a lo muy particular">
<node CREATED="1269817432198" ID="Freemind_Link_1180689073" MODIFIED="1269817522368" TEXT="En qu&#xe9; segmento de esta actividad quiero concentrarme, dados los vac&#xed;os que detect&#xe9;"/>
<node CREATED="1269817546117" ID="Freemind_Link_794224726" MODIFIED="1269817731525" TEXT="&#xbf;En qu&#xe9; rubro espec&#xed;fico hay una necesidad insatisfecha, seg&#xfa;n la lectura que hice de hacia d&#xf3;nde va al mercado?"/>
</node>
<node CREATED="1269817760797" ID="Freemind_Link_1681127597" MODIFIED="1269817900965" TEXT="S&#xf3;lo al identificar una necesidad insatisfecha podemos considerar cu&#xe1;n atractivo es el segmento elegido, para entender si podemos tener una estrategia ganadora"/>
<node CREATED="1269817928395" ID="Freemind_Link_1787274723" MODIFIED="1269818032599" TEXT="Identificar qu&#xe9; peso tienen en ese segmento los proveedores, competidores, productos sustitutos y clientes"/>
<node CREATED="1269818034149" ID="Freemind_Link_1111072045" MODIFIED="1269818050110" TEXT="Siguiendo en el ejemplo anterior:">
<node CREATED="1269818052752" ID="Freemind_Link_621040559" MODIFIED="1269818067371" TEXT="Proveedores">
<node CREATED="1269818366811" ID="Freemind_Link_1862344744" MODIFIED="1269818463315" TEXT="&#xbf;Qu&#xe9; peso tienen, por ejemplo, las imprentas en mis posibilidades de &#xe9;xito?"/>
<node CREATED="1269818471089" ID="Freemind_Link_821446496" MODIFIED="1269818560510" TEXT="&#xbf;Hay muchas imprentas o hay una sola que me va a fijar los precios, que quiera, con alto poder de negociaci&#xf3;n?"/>
</node>
<node CREATED="1269818068968" ID="Freemind_Link_569701495" MODIFIED="1269818075959" TEXT="Competidores">
<node CREATED="1269818596037" ID="Freemind_Link_408016196" MODIFIED="1269818680701" TEXT="&#xbf;Qui&#xe9;nes son mis competidores en el dise&#xf1;o de folletos promocionales y de comunicaci&#xf3;n?"/>
<node CREATED="1269818689879" ID="Freemind_Link_1552420270" MODIFIED="1269818713796" TEXT="&#xbf;Hay barreras de entrada en el mercado?"/>
<node CREATED="1269818751164" ID="Freemind_Link_245220032" MODIFIED="1269818872347" TEXT="&#xbf;Hay competidores de peso que puedan &quot;borrarme de un plumazo&quot; del mercado si se lo proponen, o la industria est&#xe1; completamente fragmentada?"/>
</node>
<node CREATED="1269818076963" ID="Freemind_Link_1424832919" MODIFIED="1269818086543" TEXT="Productos sustitutos">
<node CREATED="1269818889778" ID="Freemind_Link_1582079252" MODIFIED="1269818913273" TEXT="&#xbf;Qu&#xe9; otras opciones tiene el cliente?"/>
<node CREATED="1269818915276" ID="Freemind_Link_945317185" MODIFIED="1269819045897" TEXT="El marketing por Internet y el realizado por e-mail, son sustitutos potenciales y quienes sean proveedores de este tipo de servicio ser&#xe1;n competidores potenciales"/>
<node CREATED="1269819049366" ID="Freemind_Link_434624417" MODIFIED="1269819099788" TEXT="&#xbf;Cu&#xe1;n &quot;poderosos&quot; son esos jugadores?"/>
<node CREATED="1269819100371" ID="Freemind_Link_1405381081" MODIFIED="1269819177546" TEXT="&#xbf;Qu&#xe9; pasar&#xed;a si decidieran competir con nosotros y agregar una divisi&#xf3;n de dise&#xf1;o de folletos promocionales en su empresa?"/>
</node>
<node CREATED="1269818087267" ID="Freemind_Link_1949187875" MODIFIED="1269818091325" TEXT="Clientes">
<node CREATED="1269819205476" ID="Freemind_Link_1163691728" MODIFIED="1269819218785" TEXT="&#xbf;Qui&#xe9;nes son mis clientes?"/>
<node CREATED="1269819219602" ID="Freemind_Link_1352964166" MODIFIED="1269819318352" TEXT="&#xbf;Son las agencias de publicidad que pueden comprarme servicios para sus propios clientes, o son las empresas directamente?"/>
<node CREATED="1269819337889" ID="Freemind_Link_425944771" MODIFIED="1269819420415" TEXT="Y si son estas &#xfa;ltimas, &#xbf;qui&#xe9;nes, dentro de ellas, los gerentes de marketing o los del &#xe1;rea de compras?"/>
<node CREATED="1269819426801" ID="Freemind_Link_807608801" MODIFIED="1269819481341" TEXT="&#xbf;Conviene enfocarse en grandes empresas o en las peque&#xf1;as y medianas?"/>
</node>
</node>
</node>
<node CREATED="1269819514793" ID="Freemind_Link_1822349103" MODIFIED="1269820075746" TEXT="El haber detectado una idea con potencial no significa en absoluto que tenga el &#xe9;xito garantizado">
<icon BUILTIN="messagebox_warning"/>
</node>
<node CREATED="1269819732294" ID="Freemind_Link_1345712204" MODIFIED="1269819839554" TEXT="Al cumplir los cinco pasos de la Lupa Deductiva apenas hemos detectado un segmento del mercado en el que parece haber una oportunidad disponible"/>
<node CREATED="1269819842758" ID="Freemind_Link_1503008942" MODIFIED="1269819986264" TEXT="La respuesta a la pregunta: &#xbf;C&#xf3;mo har&#xe9; para aprovechar exitosamente esta oportunidad que parece atractiva?">
<icon BUILTIN="messagebox_warning"/>
</node>
</node>
</node>
<node CREATED="1269836858439" ID="Freemind_Link_1187941119" MODIFIED="1275779270973" POSITION="right" TEXT="El paso inicial">
<icon BUILTIN="full-3"/>
<node CREATED="1269836905991" ID="Freemind_Link_1277019121" MODIFIED="1269836949123" TEXT="Tomar la decisi&#xf3;n: el salto al vac&#xed;o">
<node CREATED="1269836960088" ID="Freemind_Link_1887782587" MODIFIED="1269836996090" TEXT="Ser emprendedor a tiempo parcial no funciona"/>
</node>
<node CREATED="1269837493066" ID="Freemind_Link_1213787388" MODIFIED="1269837518645" TEXT="Un paso necesario"/>
<node CREATED="1269837528054" ID="Freemind_Link_370966449" MODIFIED="1269837545283" TEXT="Establecer contacto"/>
<node CREATED="1269837567850" ID="Freemind_Link_845357306" MODIFIED="1269837620635" TEXT="Reunir toda la informaci&#xf3;n posible"/>
<node CREATED="1269837589205" ID="Freemind_Link_700450911" MODIFIED="1269837650545" TEXT="Aprovechar todas las oportunidades"/>
<node CREATED="1269837738143" ID="Freemind_Link_935081985" MODIFIED="1269837744165" TEXT="El regreso">
<node CREATED="1269837790868" ID="Freemind_Link_570335362" MODIFIED="1269837927730" TEXT="Lo que suele ser definitivo es la seriedad que uno puede demostrar para transformar la oportunidad en una ecuaci&#xf3;n de valor concreta"/>
</node>
</node>
<node CREATED="1269838122453" ID="Freemind_Link_657147235" MODIFIED="1275779314991" POSITION="right" TEXT="Ecuaci&#xf3;n de valor y estrategias de entrada al mercado">
<icon BUILTIN="full-4"/>
<node CREATED="1269838225132" ID="Freemind_Link_1188216184" MODIFIED="1269838474759" TEXT="Precisar la oportunidad en la ecuaci&#xf3;n del valor">
<icon BUILTIN="full-1"/>
<node CREATED="1269838583835" ID="Freemind_Link_1882490094" MODIFIED="1269840146101" TEXT="Precisar: &#xbf;Qu&#xe9; es una ecuaci&#xf3;n de valor?">
<node CREATED="1269838599692" ID="Freemind_Link_1053333874" MODIFIED="1269838769932" TEXT="Por s&#xed; mismas las cosas no tienen valor: el valor es una atribuci&#xf3;n que un sujeto les brinda"/>
<node CREATED="1269838785698" ID="Freemind_Link_809059126" MODIFIED="1269838891265" TEXT="Las cosas no son valiosas en general, sino que son valiosas para alguien, en cierta circunstancia"/>
<node CREATED="1269838913400" ID="Freemind_Link_1416019335" MODIFIED="1269839256452" TEXT="Cuando hablamos de &quot;ecuaci&#xf3;n de valor&quot; nos referimos a c&#xf3;mo desarrollar una propuesta de negocios cuyas caracter&#xed;sticas le permitan a un potencial  consumidor sentir que, al adquirir nuestros productos o servicios, se acorta la brecha entre sus aspiraciones y su realidad"/>
<node CREATED="1269839273044" ID="Freemind_Link_960904243" MODIFIED="1269839362661" TEXT="Lo que ofrecemos, entonces, es algo que genera en el cliente una percepci&#xf3;n de valor creado"/>
<node CREATED="1269839467503" ID="Freemind_Link_1728011889" MODIFIED="1269839727218" TEXT="S&#xf3;lo si contamos con un grupo de clientes potenciales que percibe que lo que damos (productos o servicios) vale m&#xe1;s que lo que nos cuesta producirlo, tendremos un negocio rentable y sostenible"/>
<node CREATED="1269839740343" ID="Freemind_Link_1942773779" MODIFIED="1269839800967" TEXT="Cuanto mejor est&#xe9; definida esta ecuaci&#xf3;n de valor creado, mayor ser&#xe1; la rentabilidad a lo largo del tiempo"/>
<node CREATED="1269839808570" ID="Freemind_Link_1087515418" MODIFIED="1269839842845" TEXT="Existe dos conceptos centrales en el proceso de determinar la ecuaci&#xf3;n del valor:">
<node CREATED="1269839851758" ID="Freemind_Link_799177045" MODIFIED="1269840003221" TEXT="El &#xe9;xito, una vez detectada la oportunidad no surge  de pensar c&#xf3;mo vamos a vender el producto o servicio que tenemos en mente, sino de entender claramente cu&#xe1;l es el producto o servicio que el consumidor potencial necesita"/>
<node CREATED="1269840025191" ID="Freemind_Link_1229991197" MODIFIED="1269840076892" TEXT="La definici&#xf3;n de nuestra estrategia comienza cuando determinamos qu&#xe9; segmento de mercado no vamos a abarcar"/>
</node>
</node>
</node>
<node CREATED="1269838289094" ID="Freemind_Link_1055561641" MODIFIED="1269838471534" TEXT="Pensar en una estrategia concreta de entrada al mercado">
<icon BUILTIN="full-2"/>
<node CREATED="1269840110032" FOLDED="true" ID="Freemind_Link_111002923" MODIFIED="1269840120704" TEXT="Concretar la necesidad">
<node CREATED="1275779362451" ID="Freemind_Link_1897950582" MODIFIED="1275779465043" TEXT="Debemos realizar un muy exhaustivo trabajo de campo en el segmento concreto del mercado"/>
<node CREATED="1275779467228" ID="Freemind_Link_761047342" MODIFIED="1275779566523" TEXT="La &#xfa;nica manera de entender qu&#xe9; que quiere un cliente es preguntar y preguntar y, sobre todo, escuchar y escuchar">
<node CREATED="1275779578785" ID="Freemind_Link_939157236" MODIFIED="1275779609137" TEXT="Existen t&#xe9;cnicas estructuradas para hacerlo">
<node CREATED="1275779610104" ID="Freemind_Link_1473360745" MODIFIED="1275779628997" TEXT="Encuestas telef&#xf3;nicas"/>
<node CREATED="1275779629727" ID="Freemind_Link_773647682" MODIFIED="1275779642708" TEXT="Encuestas personales"/>
<node CREATED="1275779643322" ID="Freemind_Link_551373696" MODIFIED="1275779657132" TEXT="Focus groups">
<node CREATED="1275779677959" ID="Freemind_Link_381109930" MODIFIED="1275779723340" TEXT="Consisten en sesiones cualitativas de trabajo con un segmento de mercado determinado">
<node CREATED="1275779758886" ID="Freemind_Link_1838899732" MODIFIED="1275779867127" TEXT="Un coordinador conduce a un grupo de personas representativas de ese segmento a trav&#xe9;s de un proceso de preguntas y consultas para que definan atributos de un producto o servicio deseado"/>
</node>
</node>
</node>
</node>
<node CREATED="1275779897366" ID="Freemind_Link_1521960821" MODIFIED="1275779958875" TEXT="Una vez determinada la oportunidad, analicemos bien el mercado para ver c&#xf3;mo convertir esa oportunidad en algo concreto:">
<node CREATED="1275779961381" ID="Freemind_Link_1643070418" MODIFIED="1275779979419" TEXT="El servicio o producto que habremos que brindar"/>
</node>
</node>
<node CREATED="1275780203674" ID="Freemind_Link_979636225" MODIFIED="1275780211324" TEXT="Distintas ecuaciones">
<node CREATED="1275780244343" ID="Freemind_Link_1820217349" MODIFIED="1275780279575" TEXT="Es posible establecer distintas ecuaciones de valor">
<node CREATED="1275780286677" ID="Freemind_Link_1131664100" MODIFIED="1275780353513" TEXT="Distintos posicionamientos y estrategias para lo que vamos a emprender"/>
</node>
</node>
<node CREATED="1275780213073" ID="Freemind_Link_1954168443" MODIFIED="1275780662245" TEXT="Definir nuestro foco"/>
</node>
